// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address account, address operator, bool approved) public {
        vm.assume(account != operator);
        vm.assume(account != address(0) && operator != address(0));

        // Set approval via internal _setApprovalForAll through safeTransferFrom? No - use setApprovalForAll public
        c.setApprovalForAll(operator, approved);

        // The general rule: isApprovedForAll(account, operator) == the last set value for that account+operator
        bool actual = c.isApprovedForAll(account, operator);

        // Note: setApprovalForAll sets for msg.sender (this test contract), not for arbitrary account.
        // So we must test that for the account that actually called setApprovalForAll.
        // But since fuzz parameters are general, we use prank to impersonate any account.
        vm.prank(account);
        c.setApprovalForAll(operator, approved);

        bool result = c.isApprovedForAll(account, operator);
        assertTrue(result == approved, "isApprovedForAll should reflect the approval set");
    }
}

